export default async function (ctx) {
  const title = ctx.element('el_title1').node;
  const subtitle = ctx.element('el_subtitle1').node;
  const bullets = ['el_bullet1', 'el_bullet2', 'el_bullet3'].map(id => ctx.element(id).node);
  // The editor's layout is the start pose. Only playback nodes receive these temporary styles.
  const baseOpacity = id => ctx.element(id).base.opacity ?? 1;
  for (const node of bullets) node.style.opacity = '0';
  await Promise.all([
    ctx.animate(title, [{ opacity: 0, transform: `${title.style.transform || ''} translateY(24px)` }, { opacity: baseOpacity('el_title1'), transform: title.style.transform || 'none' }], { duration: 520, fill: 'forwards' }),
    ctx.animate(subtitle, [{ opacity: 0 }, { opacity: baseOpacity('el_subtitle1') }], { duration: 680, fill: 'forwards' })
  ]);
  return {
    async step(index) {
      if (index === 0) {
        await Promise.all(bullets.map(async (node, i) => {
          await ctx.timer(i * 170);
          await ctx.animate(node, [{ opacity: 0, transform: `${node.style.transform || ''} translateY(18px)` }, { opacity: baseOpacity(['el_bullet1', 'el_bullet2', 'el_bullet3'][i]), transform: node.style.transform || 'none' }], { duration: 360, fill: 'forwards' });
        }));
      } else if (index === 1) {
        const photo = ctx.element('el_bgphoto').node;
        const baselineFilter = photo.style.filter || 'none';
        await ctx.animate(photo, [{ filter: baselineFilter }, { filter: `${baselineFilter === 'none' ? '' : baselineFilter} brightness(1.35)` }, { filter: baselineFilter }], { duration: 700, fill: 'forwards' });
      }
    },
    async transition({ from, to }) {
      const fromFilter = from.style.filter || 'none';
      to.style.clipPath = 'inset(0 100% 0 0)';
      await Promise.all([
        ctx.animate(to, [{ clipPath: 'inset(0 100% 0 0)' }, { clipPath: 'inset(0 0% 0 0)' }], { duration: 650, fill: 'forwards' }),
        ctx.animate(from, [{ filter: fromFilter }, { filter: `${fromFilter === 'none' ? '' : fromFilter} brightness(.45)` }], { duration: 650, fill: 'forwards' })
      ]);
      to.style.clipPath = '';
    },
    dispose() {}
  };
}

export default async function (ctx) {
  const ids = ['el_photo2', 'el_tint2', 'el_card2a', 'el_card2b'];
  const nodes = Object.fromEntries([...ids, 'el_marker2'].map(id => [id, ctx.element(id).node]));
  const original = Object.fromEntries(Object.entries(nodes).map(([id, node]) => [id, node.style.transform || '']));
  const pose = (id, x = 0, y = 0, scale = 1, turn = 0) => `${original[id]} translate(${x}px, ${y}px) scale(${scale}) rotate(${turn}deg)`;
  // Relative translations never replace project x/y/size/rotation: the original transform stays first.
  let particleAnimations = [];
  let particles = [];
  const clearParticles = () => {
    for (const animation of particleAnimations) animation.cancel();
    for (const particle of particles) particle.remove();
    particleAnimations = [];
    particles = [];
  };
  return {
    async step(index) {
      if (index === 0) {
        // A click starts a linked camera push; the two cards then rise without another click.
        await Promise.all(ids.map(id => ctx.animate(nodes[id], [
          { transform: pose(id) }, { transform: pose(id, -120, 0, .85) }
        ], { duration: 640, easing: 'ease-in-out', fill: 'forwards' })));
        ids.forEach(id => { nodes[id].style.transform = pose(id, -120, 0, .85); });
        await Promise.all(['el_card2a', 'el_card2b'].map((id, i) => ctx.animate(nodes[id], [
          { transform: pose(id, -120, 0, .85) }, { transform: pose(id, -120, i ? -60 : -30, .85, i ? -6 : 0) }
        ], { duration: 420, fill: 'forwards' })));
        nodes.el_card2a.style.transform = pose('el_card2a', -120, -30, .85);
        nodes.el_card2b.style.transform = pose('el_card2b', -120, -60, .85, -6);
      } else if (index === 1 || index === 2) {
        const marker = nodes.el_marker2;
        const start = index === 1 ? pose('el_marker2') : pose('el_marker2', -120, -80);
        const end = index === 1 ? pose('el_marker2', -120, -80) : pose('el_marker2', 280, -80);
        const before = index === 1 ? ctx.element('el_marker2').base.fill : '#facc15';
        const after = index === 1 ? '#facc15' : '#ef4444';
        await ctx.animate(marker, [{ transform: start, backgroundColor: before }, { transform: end, backgroundColor: after }], { duration: 490, fill: 'forwards' });
        marker.style.transform = end;
        marker.style.backgroundColor = after;
      } else if (index === 3) {
        // Anime.js is vendored locally; particles start at the marker's live position.
        const { animate } = await ctx.importModule('/vendor/anime.esm.min.js');
        const marker = nodes.el_marker2;
        const markerRect = marker.getBoundingClientRect();
        const rootRect = ctx.root.getBoundingClientRect();
        const scaleX = rootRect.width / ctx.project.artboard.width;
        const scaleY = rootRect.height / ctx.project.artboard.height;
        const centerX = (markerRect.left + markerRect.width / 2 - rootRect.left) / scaleX;
        const centerY = (markerRect.top + markerRect.height / 2 - rootRect.top) / scaleY;
        for (let i = 0; i < 20; i++) {
          const dot = document.createElement('span');
          dot.style.cssText = `position:absolute;pointer-events:none;width:9px;height:9px;border-radius:50%;background:${i % 2 ? '#facc15' : '#38bdf8'};left:${centerX}px;top:${centerY}px;z-index:9999`;
          ctx.root.append(dot);
          particles.push(dot);
          const angle = i * Math.PI * 2 / 20;
          particleAnimations.push(animate(dot, { x: Math.cos(angle) * (70 + i * 3), y: Math.sin(angle) * (70 + i * 3), opacity: [1, 0], scale: [1, .25], duration: 720, ease: 'out(3)' }));
        }
        ctx.signal.addEventListener('abort', clearParticles, { once: true });
        const photoFilter = nodes.el_photo2.style.filter || 'none';
        const tintOpacity = ctx.element('el_tint2').base.opacity ?? 1;
        await Promise.all([
          ctx.animate(nodes.el_photo2, [{ filter: photoFilter }, { filter: `${photoFilter === 'none' ? '' : photoFilter} grayscale(1)` }], { duration: 720, fill: 'forwards' }),
          ctx.animate(nodes.el_tint2, [{ opacity: tintOpacity }, { opacity: 0 }], { duration: 720, fill: 'forwards' }),
          ctx.timer(730)
        ]);
        clearParticles();
      }
    },
    async transition({ from, to }) {
      const fromOpacity = Number.parseFloat(from.style.opacity || '1');
      const toOpacity = Number.parseFloat(to.style.opacity || '1');
      await Promise.all([
        ctx.animate(from, [{ opacity: fromOpacity, transform: 'translateX(0)' }, { opacity: 0, transform: 'translateX(-8%)' }], { duration: 600, fill: 'forwards' }),
        ctx.animate(to, [{ opacity: 0, transform: 'translateX(8%)' }, { opacity: toOpacity, transform: 'translateX(0)' }], { duration: 600, fill: 'forwards' })
      ]);
    },
    dispose() { clearParticles(); }
  };
}

export default async function (ctx) {
  const photo = ctx.element('el_clipimg3').node;
  const group = ctx.element('el_group3').node;
  const triangle = ctx.element('el_gtri3').node;
  const groupOrigin = group.style.transform || '';
  const triangleOrigin = triangle.style.transform || '';
  return {
    async step(index) {
      if (index === 0) {
        await ctx.animate(photo, [
          { clipPath: 'polygon(50% 0%,100% 50%,50% 100%,0% 50%)' },
          { clipPath: 'polygon(25% 0%,75% 0%,100% 50%,75% 100%,25% 100%,0% 50%)' }
        ], { duration: 700, fill: 'forwards' });
      } else if (index === 1) {
        await Promise.all([
          ctx.animate(group, [{ transform: groupOrigin || 'none' }, { transform: `${groupOrigin} translateX(-80px) scale(1.05)` }], { duration: 560, fill: 'forwards' }),
          ctx.animate(triangle, [{ transform: triangleOrigin || 'none' }, { transform: `${triangleOrigin} rotate(180deg)` }], { duration: 560, fill: 'forwards' })
        ]);
      }
    },
    async transition({ from, to }) {
      if (!to) return;
      const toOpacity = Number.parseFloat(to.style.opacity || '1');
      await ctx.animate(to, [{ opacity: 0 }, { opacity: toOpacity }], { duration: 500, fill: 'forwards' });
    },
    dispose() {}
  };
}
